UPDATE banks SET questions_json = '[{"id":1,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个半径给r，求圆的面积。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double r, area;\\n    scanf(\\"%lf\\", &r);\\n    area = 3.1415926 * r * r;\\n    printf(\\"面积:%.2f\\\\n\\", area);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：定义双精度浮点数，公式为 3.1415926 * r * r。","codeLanguage":"c","memoryAid":"定义双精度浮点数，公式为 3.1415926 * r * r。"},{"id":2,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：从键盘输入一个浮点数，然后分别输出该数的整数部分和小数部分。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double num;\\n    scanf(\\"%lf\\", &num);\\n    int zheng = (int)num;\\n    double xiao = num - zheng;\\n    printf(\\"整数:%d, 小数:%f\\\\n\\", zheng, xiao);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：使用强转 (int) 截断获取整数，原数减去整数即得小数。","codeLanguage":"c","memoryAid":"使用强转 (int) 截断获取整数，原数减去整数即得小数。"},{"id":3,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上输入小写字母，显示这个小写字母和大写字母以及对应的ASCII码。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\"%c\\", &ch);\\n    printf(\\"小写:%c(ASCII:%d)\\\\n\\", ch, ch);\\n    printf(\\"大写:%c(ASCII:%d)\\\\n\\", ch - 32, ch - 32);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：大小写字母ASCII码相差32。","codeLanguage":"c","memoryAid":"大小写字母ASCII码相差32。"},{"id":4,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输出以下图形（顺序结构直接打印）","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    printf(\\"   *\\\\n\\");\\n    printf(\\"  ***\\\\n\\");\\n    printf(\\" *****\\\\n\\");\\n    printf(\\"*******\\\\n\\");\\n    printf(\\" *****\\\\n\\");\\n    printf(\\"  ***\\\\n\\");\\n    printf(\\"   *\\\\n\\");\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：考场直接用 printf 拼出菱形，最快最稳。","codeLanguage":"c","memoryAid":"考场直接用 printf 拼出菱形，最快最稳。"},{"id":5,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个5位的正整数，分别求出它每位上的数值，然后逆序输出（不限制位数版）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int num;\\n    scanf(\\"%d\\", &num);\\n    while (num > 0) {\\n        printf(\\"%d \\", num % 10);\\n        num /= 10;\\n    }\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：%10取尾数，/10剥除尾数，用 while 循环解决。","codeLanguage":"c","memoryAid":"%10取尾数，/10剥除尾数，用 while 循环解决。"},{"id":6,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：通过键盘上输入一位同学的5门课程的成绩，计算该同学的平均成绩和总成绩并输出。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double c1, c2, c3, c4, c5, sum, avg;\\n    scanf(\\"%lf %lf %lf %lf %lf\\", &c1, &c2, &c3, &c4, &c5);\\n    sum = c1 + c2 + c3 + c4 + c5;\\n    avg = sum / 5.0;\\n    printf(\\"总分:%.2f, 平均分:%.2f\\\\n\\", sum, avg);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。","codeLanguage":"c","memoryAid":""},{"id":7,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个三角形的三边的值分别给a、b、c，求得并输出该三角形的面积。","options":[],"answer":"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a, b, c, s, area;\\n    scanf(\\"%lf %lf %lf\\", &a, &b, &c);\\n    s = (a + b + c) / 2.0;\\n    area = sqrt(s * (s - a) * (s - b) * (s - c));\\n    printf(\\"面积:%.2f\\\\n\\", area);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：海伦公式 s = (a+b+c)/2, area = sqrt(s*(s-a)*(s-b)*(s-c))。","codeLanguage":"c","memoryAid":"海伦公式 s = (a+b+c)/2, area = sqrt(s*(s-a)*(s-b)*(s-c))。"},{"id":8,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个数值给自变量x和y，要求实现2个变量之间的数值交换（不能使用交换的思想/第三方变量）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double x, y;\\n    scanf(\\"%lf %lf\\", &x, &y);\\n    x = x + y;\\n    y = x - y;\\n    x = x - y;\\n    printf(\\"交换后: x=%.2f, y=%.2f\\\\n\\", x, y);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：利用加减法做差值的逆向代换。","codeLanguage":"c","memoryAid":"利用加减法做差值的逆向代换。"},{"id":9,"type":"code","category":"顺序结构程序练习","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入一个字母（假设是大写字母），将其替换为字母表中后移3位的字母（凯撒加密，如果超过Z则绕回A）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\"%c\\", &ch);\\n    if (ch >= \'A\' && ch <= \'Z\') {\\n        ch = (ch - \'A\' + 3) % 26 + \'A\';\\n    }\\n    printf(\\"加密后:%c\\\\n\\", ch);\\n    return 0;\\n}","explanation":"这是顺序结构程序练习的经典程序。记忆要点：利用 % 26 实现循环回绕。","codeLanguage":"c","memoryAid":"利用 % 26 实现循环回绕。"},{"id":10,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数给x，判断其是奇数还是偶数？","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int x;\\n    scanf(\\"%d\\", &x);\\n    if (x % 2 == 0) printf(\\"偶数\\\\n\\");\\n    else printf(\\"奇数\\\\n\\");\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":11,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个年份，判断其实闰年还是平年？","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int y;\\n    scanf(\\"%d\\", &y);\\n    if ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)) {\\n        printf(\\"闰年\\\\n\\");\\n    } else {\\n        printf(\\"平年\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。记忆要点：四年一闰百年不闰，或四百年一闰。","codeLanguage":"c","memoryAid":"四年一闰百年不闰，或四百年一闰。"},{"id":12,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入3个数值分别给变量a、b、c，求得它们的最大值。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int a, b, c, max;\\n    scanf(\\"%d %d %d\\", &a, &b, &c);\\n    max = a;\\n    if (b > max) max = b;\\n    if (c > max) max = c;\\n    printf(\\"最大值:%d\\\\n\\", max);\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":13,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入3个数值分别给变量a、b、c，要求按照从小到大的顺序输出。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int a, b, c, t;\\n    scanf(\\"%d %d %d\\", &a, &b, &c);\\n    if (a > b) { t = a; a = b; b = t; }\\n    if (a > c) { t = a; a = c; c = t; }\\n    if (b > c) { t = b; b = c; c = t; }\\n    printf(\\"%d %d %d\\\\n\\", a, b, c);\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。记忆要点：两两比较，三次代换，小的换到前面。","codeLanguage":"c","memoryAid":"两两比较，三次代换，小的换到前面。"},{"id":14,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入a，b，c的值，求得并输出当y=0时，y=ax2+bx+c的解。","options":[],"answer":"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a, b, c, disc, x1, x2;\\n    scanf(\\"%lf %lf %lf\\", &a, &b, &c);\\n    disc = b * b - 4 * a * c;\\n    if (disc >= 0) {\\n        x1 = (-b + sqrt(disc)) / (2 * a);\\n        x2 = (-b - sqrt(disc)) / (2 * a);\\n        printf(\\"x1=%.2f, x2=%.2f\\\\n\\", x1, x2);\\n    } else {\\n        printf(\\"无实根\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":15,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数，判断其能被3、5整除的情况。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int n;\\n    scanf(\\"%d\\", &n);\\n    if (n % 3 == 0 && n % 5 == 0) printf(\\"该数能同时被3和5整除\\\\n\\");\\n    else if (n % 3 == 0 || n % 5 == 0) printf(\\"该数能被其中一个数整除\\\\n\\");\\n    else printf(\\"该数既不能被3整除，也不能被5整除\\\\n\\");\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":16,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：将输入的大写字母转换为小写字母。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\"%c\\", &ch);\\n    if (ch >= \'A\' && ch <= \'Z\') ch += 32;\\n    printf(\\"%c\\\\n\\", ch);\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":17,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个年月日，计算并输出这天是该年的第几天？","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int y, m, d, days = 0;\\n    int months[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};\\n    scanf(\\"%d %d %d\\", &y, &m, &d);\\n    if ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)) months[2] = 29;\\n    for (int i = 1; i < m; i++) days += months[i];\\n    days += d;\\n    printf(\\"第%d天\\\\n\\", days);\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。记忆要点：用静态数组查表累加，注意闰年修正。","codeLanguage":"c","memoryAid":"用静态数组查表累加，注意闰年修正。"},{"id":18,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入某个同学的期末成绩，将其转换为对应的5级等级制成绩输出。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int s;\\n    scanf(\\"%d\\", &s);\\n    if (s < 0 || s > 100) return 0;\\n    switch (s / 10) {\\n        case 10:\\n        case 9:  printf(\\"优\\\\n\\"); break;\\n        case 8:  printf(\\"良\\\\n\\"); break;\\n        case 7:  printf(\\"中\\\\n\\"); break;\\n        case 6:  printf(\\"及格\\\\n\\"); break;\\n        default: printf(\\"不及格\\\\n\\"); break;\\n    }\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。记忆要点：利用 score / 10 将成绩归类，使用 switch-case。","codeLanguage":"c","memoryAid":"利用 score / 10 将成绩归类，使用 switch-case。"},{"id":19,"type":"code","category":"选择结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个数值之间的四则运算表达式，输出结果（例如输入：10+20 输出30）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double a, b;\\n    char op;\\n    if (scanf(\\"%lf%c%lf\\", &a, &op, &b) == 3) {\\n        switch (op) {\\n            case \'+\': printf(\\"%.2f\\\\n\\", a + b); break;\\n            case \'-\': printf(\\"%.2f\\\\n\\", a - b); break;\\n            case \'*\': printf(\\"%.2f\\\\n\\", a * b); break;\\n            case \'/\': printf(\\"%.2f\\\\n\\", a / b); break;\\n        }\\n    }\\n    return 0;\\n}","explanation":"这是选择结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":20,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+2+3+……+98+99+100","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int s = 0;\\n    for (int i = 1; i <= 100; i++) s += i;\\n    printf(\\"s = %d\\\\n\\", s);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":21,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+3+5+……+97+99","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int s = 0;\\n    for (int i = 1; i <= 99; i += 2) s += i;\\n    printf(\\"s = %d\\\\n\\", s);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":22,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求s=1-3+5-7+……+97-99","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int s = 0, sign = 1;\\n    for (int i = 1; i <= 99; i += 2) {\\n        s += sign * i;\\n        sign = -sign;\\n    }\\n    printf(\\"s = %d\\\\n\\", s);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：利用 sign = -sign 每次循环切换正负。","codeLanguage":"c","memoryAid":"利用 sign = -sign 每次循环切换正负。"},{"id":23,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求π的值，已知π/4≈1-1/3+1/5-1/7+……计算至某项的绝对值小于1E-6为止。","options":[],"answer":"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double sum = 0, term = 1.0, i = 1.0;\\n    int sign = 1;\\n    while (fabs(term) >= 1e-6) {\\n        sum += term;\\n        i += 2;\\n        sign = -sign;\\n        term = sign / i;\\n    }\\n    printf(\\"pi = %f\\\\n\\", sum * 4);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":24,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：已知s=1+11+111+1111+……，一直加到n位1，n的值自己输入。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int n, s = 0, t = 0;\\n    scanf(\\"%d\\", &n);\\n    for (int i = 1; i <= n; i++) {\\n        t = t * 10 + 1;\\n        s += t;\\n    }\\n    printf(\\"s = %d\\\\n\\", s);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：当前项公式 t = t * 10 + 1。","codeLanguage":"c","memoryAid":"当前项公式 t = t * 10 + 1。"},{"id":25,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入30名学生的程序设计成绩，计算并输出所有学生的平均分和最高成绩。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double score, sum = 0, max = 0;\\n    for (int i = 0; i < 30; i++) {\\n        scanf(\\"%lf\\", &score);\\n        sum += score;\\n        if (score > max) max = score;\\n    }\\n    printf(\\"平均分:%.2f, 最高分:%.2f\\\\n\\", sum / 30.0, max);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":26,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入一批整数，输入0时表示输入结束，求正整数的个数以及它们的和。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int n, count = 0, sum = 0;\\n    while (1) {\\n        scanf(\\"%d\\", &n);\\n        if (n == 0) break;\\n        if (n > 0) { count++; sum += n; }\\n    }\\n    printf(\\"个数:%d, 和:%d\\\\n\\", count, sum);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":27,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个正整数给自变量x和y，要求求得它们之间的最大公约数和最小公倍数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int x, y, a, b, t;\\n    scanf(\\"%d %d\\", &x, &y);\\n    a = x; b = y;\\n    while (b != 0) { t = a % b; a = b; b = t; }\\n    printf(\\"最大公约数:%d\\\\n\\", a);\\n    printf(\\"最小公倍数:%d\\\\n\\", (x * y) / a);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：必考辗转相除法。","codeLanguage":"c","memoryAid":"必考辗转相除法。"},{"id":28,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数，判断其是否是素数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int n, is_prime = 1;\\n    scanf(\\"%d\\", &n);\\n    if (n < 2) is_prime = 0;\\n    for (int i = 2; i * i <= n; i++) {\\n        if (n % i == 0) { is_prime = 0; break; }\\n    }\\n    if (is_prime) printf(\\"是素数\\\\n\\");\\n    else printf(\\"不是素数\\\\n\\");\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":29,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：打印出所有的“水仙花数”。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int i = 100; i <= 999; i++) {\\n        int a = i / 100, b = (i / 10) % 10, c = i % 10;\\n        if (a*a*a + b*b*b + c*c*c == i) printf(\\"%d \\", i);\\n    }\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":30,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上任意输入2个正整数给a and b，计算a and b之间所有整数（包括a and b）的累加和。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int a, b, sum = 0;\\n    scanf(\\"%d %d\\", &a, &b);\\n    int start = (a < b) ? a : b;\\n    int end = (a > b) ? a : b;\\n    for (int i = start; i <= end; i++) sum += i;\\n    printf(\\"和:%d\\\\n\\", sum);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":31,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：小猴摘桃问题（第7天早上剩1个，求总数）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int count = 1;\\n    for (int i = 1; i <= 6; i++) count = (count + 1) * 2;\\n    printf(\\"总数:%d\\\\n\\", count);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：倒推法，前一天 = (今天 + 1) * 2。","codeLanguage":"c","memoryAid":"倒推法，前一天 = (今天 + 1) * 2。"},{"id":32,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+2！+3！+4！+……+19！+20！","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double sum = 0, term = 1;\\n    for (int i = 1; i <= 20; i++) { term *= i; sum += term; }\\n    printf(\\"s = %.0f\\\\n\\", sum);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：单层循环，累乘即得当前项。注意大数用 double。","codeLanguage":"c","memoryAid":"单层循环，累乘即得当前项。注意大数用 double。"},{"id":33,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：编写程序输出9*9乘法表。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int i = 1; i <= 9; i++) {\\n        for (int j = 1; j <= i; j++) printf(\\"%d*%d=%-2d \\", j, i, i * j);\\n        printf(\\"\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":34,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：用循环的思想打印星号菱形图形。","options":[],"answer":"#include <stdio.h>\\n#include <stdlib.h>\\nint main() {\\n    for (int i = -3; i <= 3; i++) {\\n        int spaces = abs(i), stars = 7 - 2 * spaces;\\n        for (int j = 0; j < spaces; j++) printf(\\" \\");\\n        for (int j = 0; j < stars; j++) printf(\\"*\\");\\n        printf(\\"\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：坐标轴绝对值对称法，绝对精简高端。","codeLanguage":"c","memoryAid":"坐标轴绝对值对称法，绝对精简高端。"},{"id":35,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输出1000以内所有的质数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int i = 2; i <= 1000; i++) {\\n        int is_prime = 1;\\n        for (int j = 2; j * j <= i; j++) {\\n            if (i % j == 0) { is_prime = 0; break; }\\n        }\\n        if (is_prime) printf(\\"%d \\", i);\\n    }\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":36,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入1000以内所有的完数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int i = 1; i <= 1000; i++) {\\n        int sum = 0;\\n        for (int j = 1; j < i; j++) if (i % j == 0) sum += j;\\n        if (sum == i) printf(\\"%d \\", i);\\n    }\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":37,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：红球3白球5黑球6任取8个至少一白，输出组合并计算概率。","options":[],"answer":"#include <stdio.h>\\nlong comb(int n, int m) {\\n    if (m < 0 || m > n) return 0;\\n    long res = 1;\\n    for (int i = 1; i <= m; i++) res = res * (n - i + 1) / i;\\n    return res;\\n}\\nint main() {\\n    long valid_ways = 0;\\n    for (int r = 0; r <= 3; r++) {\\n        for (int w = 1; w <= 5; w++) {\\n            for (int b = 0; b <= 6; b++) {\\n                if (r + w + b == 8) {\\n                    printf(\\"红:%d, 白:%d, 黑:%d\\\\n\\", r, w, b);\\n                    valid_ways += comb(3, r) * comb(5, w) * comb(6, b);\\n                }\\n            }\\n        }\\n    }\\n    printf(\\"概率为: %f\\\\n\\", (double)valid_ways / comb(14, 8));\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：至少一白即 w 从 1 开始，总事件组合数为 C(14, 8) = 3003。","codeLanguage":"c","memoryAid":"至少一白即 w 从 1 开始，总事件组合数为 C(14, 8) = 3003。"},{"id":38,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：有若干只鸡兔同在一个笼子里，有36个头，100只脚，问各有多少只鸡和兔？","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int j = 0; j <= 36; j++) {\\n        int t = 36 - j;\\n        if (j * 2 + t * 4 == 100) printf(\\"鸡:%d, 兔:%d\\\\n\\", j, t);\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":39,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：0-9可以组成多少个没有重复的3位偶数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int count = 0;\\n    for (int a = 1; a <= 9; a++) {\\n        for (int b = 0; b <= 9; b++) {\\n            for (int c = 0; c <= 8; c += 2) {\\n                if (a != b && b != c && a != c) count++;\\n            }\\n        }\\n    }\\n    printf(\\"方案数:%d\\\\n\\", count);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":40,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：求出用1元人民币兑换1分，2分，5分硬币的所有兑换方案，要求硬币总数是70枚。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int a = 0; a <= 70; a++) {\\n        for (int b = 0; b <= 50; b++) {\\n            int c = 70 - a - b;\\n            if (c >= 0 && a * 1 + b * 2 + c * 5 == 100) {\\n                printf(\\"1分:%d, 2分:%d, 5分:%d\\\\n\\", a, b, c);\\n            }\\n        }\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":41,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入x的值，求 sinx 的近似值直到绝对值小于 1E-6。","options":[],"answer":"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double x, sum, term;\\n    scanf(\\"%lf\\", &x);\\n    sum = 0; term = x; int i = 1;\\n    while (fabs(term) >= 1e-6) {\\n        sum += term;\\n        i += 2;\\n        term = -term * x * x / ((i - 1) * i);\\n    }\\n    printf(\\"sinx ≈ %f\\\\n\\", sum);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":42,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：百鸡问题（母鸡3元, 公鸡2元, 小鸡0.5元，100元买100只鸡）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int m = 0; m <= 33; m++) {\\n        for (int g = 0; g <= 50; g++) {\\n            int x = 100 - m - g;\\n            if (x >= 0 && m * 3.0 + g * 2.0 + x * 0.5 == 100.0) {\\n                printf(\\"母鸡:%d, 公鸡:%d, 小鸡:%d\\\\n\\", m, g, x);\\n            }\\n        }\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":43,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：高校排考方案（周一到周五排3门，高数最早，计算机不在周四）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int count = 0;\\n    for (int m = 1; m <= 5; m++) {\\n        for (int c = 1; c <= 5; c++) {\\n            for (int e = 1; e <= 5; e++) {\\n                if (m != c && c != e && m != e) {\\n                    if (m < c && m < e && c != 4) {\\n                        count++;\\n                        printf(\\"高数:周%d, 计算机:周%d, 英语:周%d\\\\n\\", m, c, e);\\n                    }\\n                }\\n            }\\n        }\\n    }\\n    printf(\\"总排考方案数:%d\\\\n\\", count);\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":44,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：某君每次吹熄与年龄相同根数的蜡烛，一共吹熄了236根，问从多少岁开始过生日。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int start = 1; start <= 100; start++) {\\n        int sum = 0;\\n        for (int age = start; age <= 100; age++) {\\n            sum += age;\\n            if (sum == 236) printf(\\"从%d岁开始\\\\n\\", start);\\n        }\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。","codeLanguage":"c","memoryAid":""},{"id":45,"type":"code","category":"循环结构程序设计","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：海盗平分4瓶酒方程推断（1/a + 1/b + 1/c + 1/d == 1）。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    for (int a = 4; a <= 20; a++) {\\n        for (int b = 3; b < a; b++) {\\n            for (int c = 2; c < b; c++) {\\n                for (int d = 1; d < c; d++) {\\n                    if (b*c*d + a*c*d + a*b*d + a*b*c == a*b*c*d) {\\n                        printf(\\"总共%d人, 依次剩:%d, %d, %d人\\\\n\\", a, b, c, d);\\n                    }\\n                }\\n            }\\n        }\\n    }\\n    return 0;\\n}","explanation":"这是循环结构程序设计的经典程序。记忆要点：由于全倒，通分化简为整型判断方程。","codeLanguage":"c","memoryAid":"由于全倒，通分化简为整型判断方程。"},{"id":46,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入一个寝室6位同学的身高，要求按照从小到大的顺序输出。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double h[6], t;\\n    for (int i = 0; i < 6; i++) scanf(\\"%lf\\", &h[i]);\\n    for (int i = 0; i < 5; i++) {\\n        for (int j = 0; j < 5 - i; j++) {\\n            if (h[j] > h[j+1]) { t = h[j]; h[j] = h[j+1]; h[j+1] = t; }\\n        }\\n    }\\n    for (int i = 0; i < 6; i++) printf(\\"%.2f \\", h[i]);\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：极高频经典冒泡排序。","codeLanguage":"c","memoryAid":"极高频经典冒泡排序。"},{"id":47,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入某班级所有同学的程序设计技术期末成绩（33人），要求输出最好的2位同学的成绩。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double score, max1 = -1, max2 = -1;\\n    for (int i = 0; i < 33; i++) {\\n        scanf(\\"%lf\\", &score);\\n        if (score > max1) { max2 = max1; max1 = score; }\\n        else if (score > max2) { max2 = score; }\\n    }\\n    printf(\\"第一名:%.2f, 第二名:%.2f\\\\n\\", max1, max2);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":48,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：校园歌手大赛，一共有7位裁判打分，去掉一个最高分和最低分算平均分。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    double score, sum = 0, max = -1, min = 101;\\n    for (int i = 0; i < 7; i++) {\\n        scanf(\\"%lf\\", &score);\\n        sum += score;\\n        if (score > max) max = score;\\n        if (score < min) min = score;\\n    }\\n    printf(\\"最后得分:%.2f\\\\n\\", (sum - max - min) / 5.0);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":49,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：在数组中存储10个同学C语言的成绩，计算平均成绩，并输出与平均值最接近的数。","options":[],"answer":"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a[10], sum = 0, avg, ans, min_diff;\\n    for (int i = 0; i < 10; i++) { scanf(\\"%lf\\", &a[i]); sum += a[i]; }\\n    avg = sum / 10.0; min_diff = fabs(a[0] - avg); ans = a[0];\\n    for (int i = 1; i < 10; i++) {\\n        if (fabs(a[i] - avg) < min_diff) { min_diff = fabs(a[i] - avg); ans = a[i]; }\\n    }\\n    printf(\\"最接近的数:%.2f\\\\n\\", ans);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":50,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入班级33位同学期末成绩，分别统计优，良，中，及格，不及格人数及百分比。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int score, counts[5] = {0};\\n    for (int i = 0; i < 33; i++) {\\n        scanf(\\"%d\\", &score);\\n        if (score >= 90) counts[0]++;\\n        else if (score >= 80) counts[1]++;\\n        else if (score >= 70) counts[2]++;\\n        else if (score >= 60) counts[3]++;\\n        else counts[4]++;\\n    }\\n    char *labels[] = {\\"优\\", \\"良\\", \\"中\\", \\"及格\\", \\"不及格\\"};\\n    for (int i = 0; i < 5; i++) {\\n        printf(\\"%s: %d人, 占比:%.2f%%\\\\n\\", labels[i], counts[i], (counts[i] / 33.0) * 100);\\n    }\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":51,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：FIBONACCI 数列，请编程输出该数列的前20项。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int f[20] = {1, 1};\\n    printf(\\"1\\\\n1\\\\n\\");\\n    for (int i = 2; i < 20; i++) {\\n        f[i] = f[i-1] + f[i-2];\\n        printf(\\"%d\\\\n\\", f[i]);\\n    }\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":52,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：给一个一维数组任意输入6个整数，要求建立一个循环右移方阵并输出。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int a[6];\\n    for (int i = 0; i < 6; i++) scanf(\\"%d\\", &a[i]);\\n    for (int i = 0; i < 6; i++) {\\n        for (int j = 0; j < 6; j++) printf(\\"%d\\\\t\\", a[(j - i + 6) % 6]);\\n        printf(\\"\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：利用一维数组配合数学公式 (j - i + 6) % 6 映射，无需开二维数组。","codeLanguage":"c","memoryAid":"利用一维数组配合数学公式 (j - i + 6) % 6 映射，无需开二维数组。"},{"id":53,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：医院想统计某项疾病患病与年龄的关系，按 0-18、19-35、36-60、61以上统计比例。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    int n, age, c[4] = {0};\\n    scanf(\\"%d\\", &n);\\n    for (int i = 0; i < n; i++) {\\n        scanf(\\"%d\\", &age);\\n        if (age <= 18) c[0]++;\\n        else if (age <= 35) c[1]++;\\n        else if (age <= 60) c[2]++;\\n        else c[3]++;\\n    }\\n    for (int i = 0; i < 4; i++) printf(\\"段%d比例:%.2f%%\\\\n\\", i+1, (c[i]/(double)n)*100);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":54,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，统计其中英文字符 a 的个数，不区分大小写。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[200]; int count = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (s[i] == \'a\' || s[i] == \'A\') count++;\\n    }\\n    printf(\\"count = %d\\\\n\\", count);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":55,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，分别统计出其中26个英文字母各自的个数，不区分大小写。","options":[],"answer":"#include <stdio.h>\\n#include <ctype.h>\\nint main() {\\n    char s[200]; int count[26] = {0};\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (isalpha(s[i])) count[tolower(s[i]) - \'a\']++;\\n    }\\n    for (int i = 0; i < 26; i++) {\\n        if (count[i] > 0) printf(\\"%c: %d\\\\n\\", \'a\' + i, count[i]);\\n    }\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":56,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，分别统计出英文字符、数字字符、空格字符和其他字符等四大类字符各自的个数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[200]; int l=0, d=0, sp=0, o=0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if ((s[i]>=\'a\'&&s[i]<=\'z\')||(s[i]>=\'A\'&&s[i]<=\'Z\')) l++;\\n        else if (s[i]>=\'0\'&&s[i]<=\'9\') d++;\\n        else if (s[i]==\' \') sp++;\\n        else o++;\\n    }\\n    printf(\\"字母:%d, 数字:%d, 空格:%d, 其他:%d\\\\n\\", l, d, sp, o);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":57,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，统计其中英文单词的个数。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[200]; int count = 0, word = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (s[i] == \' \') word = 0;\\n        else if (word == 0) { word = 1; count++; }\\n    }\\n    printf(\\"单词数:%d\\\\n\\", count);\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：状态量 word 判定单词开头计数。","codeLanguage":"c","memoryAid":"状态量 word 判定单词开头计数。"},{"id":58,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：输入4个国家的名字，按照从小到大的顺序进行排序并输出。","options":[],"answer":"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char country[4][50], temp[50];\\n    for (int i = 0; i < 4; i++) gets(country[i]);\\n    for (int i = 0; i < 3; i++) {\\n        for (int j = 0; j < 3 - i; j++) {\\n            if (strcmp(country[j], country[j+1]) > 0) {\\n                strcpy(temp, country[j]);\\n                strcpy(country[j], country[j+1]);\\n                strcpy(country[j+1], temp);\\n            }\\n        }\\n    }\\n    for (int i = 0; i < 4; i++) puts(country[i]);\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：二维字符数组，strcmp 比较，strcpy 交换。","codeLanguage":"c","memoryAid":"二维字符数组，strcmp 比较，strcpy 交换。"},{"id":59,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上任意输入一个字符串，将该字符串中的字符按照 ASCII 码的顺序从小到大的顺序排序后输出。","options":[],"answer":"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char s[100], t;\\n    gets(s); int len = strlen(s);\\n    for (int i = 0; i < len - 1; i++) {\\n        for (int j = 0; j < len - 1 - i; j++) {\\n            if (s[j] > s[j+1]) { t = s[j]; s[j] = s[j+1]; s[j+1] = t; }\\n        }\\n    }\\n    puts(s);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":60,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，将其中所有的数字字符删除,再输出结果(采用的是后面的往前覆盖的思路设计)。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[200]; int j = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (!(s[i] >= \'0\' && s[i] <= \'9\')) { s[j++] = s[i]; }\\n    }\\n    s[j] = \'\\\\0\';\\n    puts(s);\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：双指针覆盖。","codeLanguage":"c","memoryAid":"双指针覆盖。"},{"id":61,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：编程实现输入一行字符，将其中重复出现的字符全部删除。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[200]; int visited[256] = {0};\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (visited[(unsigned char)s[i]] == 0) {\\n            putchar(s[i]);\\n            visited[(unsigned char)s[i]] = 1;\\n        }\\n    }\\n    printf(\\"\\\\n\\");\\n    return 0;\\n}","explanation":"这是数组的经典程序。记忆要点：大小 256 的 visited 状态数组去重法。","codeLanguage":"c","memoryAid":"大小 256 的 visited 状态数组去重法。"},{"id":62,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：要将 \'China\' 译成密码，译码规律是：用原来字母后面的第4个字母代替原来的字母。","options":[],"answer":"#include <stdio.h>\\nint main() {\\n    char s[] = \\"China\\";\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) s[i] = s[i] + 4;\\n    puts(s);\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""},{"id":63,"type":"code","category":"数组","difficulty":2,"question":"请默写以下程序的完整代码：\\n\\n**题目**：石头剪子布游戏结果判断。","options":[],"answer":"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char p1[10], p2[10];\\n    scanf(\\"%s %s\\", p1, p2);\\n    if (strcmp(p1, p2) == 0) printf(\\"平局\\\\n\\");\\n    else if ((strcmp(p1, \\"石头\\")==0 && strcmp(p2, \\"剪刀\\")==0) ||\\n             (strcmp(p1, \\"剪刀\\")==0 && strcmp(p2, \\"布\\")==0) ||\\n             (strcmp(p1, \\"布\\")==0 && strcmp(p2, \\"石头\\")==0)) {\\n        printf(\\"玩家1获胜\\\\n\\");\\n    } else {\\n        printf(\\"玩家2获胜\\\\n\\");\\n    }\\n    return 0;\\n}","explanation":"这是数组的经典程序。","codeLanguage":"c","memoryAid":""}]' WHERE id = 'c-language-2026-code';